46	  // Start at 1 so we can skip the ^curl part
47	  for (let i = 1; i < parseEntries.length; i++) {
48	    let parseEntry = parseEntries[i];
49	    // trim leading spaces between parsed entries
50	    // regex won't match otherwise (e.g.    -H 'Content-Type: application/json')
51	    if (typeof parseEntry === 'string') {
52	      parseEntry = parseEntry.trim();
53	    }
54	
55	    if (typeof parseEntry === 'string' && parseEntry.match(/^-{1,2}[\w-]+/)) {
56	      const isSingleDash = parseEntry[0] === '-' && parseEntry[1] !== '-';
57	      let name = parseEntry.replace(/^-{1,2}/, '');
58	
59	      if (!SUPPORTED_ARGS.includes(name)) {
60	        continue;
61	      }
62	
63	      let value;
64	      const nextEntry = parseEntries[i + 1];
65	      if (isSingleDash && name.length > 1) {
66	        // Handle squished arguments like -XPOST
67	        value = name.slice(1);
68	        name = name.slice(0, 1);
69	      } else if (typeof nextEntry === 'string' && !nextEntry.startsWith('-')) {
70	        // Next arg is not a flag, so assign it as the value
71	        value = nextEntry;
72	        i++; // Skip next one
73	      } else {
74	        value = true;
75	      }
76	
77	      if (!pairsByName[name]) {
78	        pairsByName[name] = [value];
79	      } else {
80	        pairsByName[name].push(value);
81	      }
82	    } else if (parseEntry) {
83	      singletons.push(parseEntry);
84	    }
85	  }
86	  return { pairsByName, singletons };
